Task: Players need to extract resources from various sources in their mining operations. Your task is to complete the `ResourceSource` base class and its concrete subclasses, `OreVein` and `CrystalDeposit`.
Ensure that the `extract` method demonstrates proper abstraction by requiring subclasses to implement it, and include robust input validation for the extraction quantity.

Submitted code:
```
class ResourceSource {
  constructor(location) {
    this.location = location;
  }

  // Enforces an "Abstract Interface"
  extract(quantity) {
    throw new Error("extract() must be implemented by subclasses.");
  }
}

class OreVein extends ResourceSource {
  constructor(location, oreType) {
    super(location);
    this.oreType = oreType;
  }

  extract(quantity) {
    // Input validation for business logic
    if (quantity <= 0) {
      throw new Error("Quantity must be a positive number.");
    }
    return `Extracted ${quantity} units of ${this.oreType} from ${this.location}.`;
  }
}

class CrystalDeposit extends ResourceSource {
  constructor(location, crystalColor) {
    super(location);
    this.crystalColor = crystalColor;
  }

  extract(quantity) {
    // Input validation for business logic
    if (quantity <= 0) {
      throw new Error("Quantity must be a positive number.");
    }
    return `Mined ${quantity} units of ${this.crystalColor} crystals from ${this.location}.`;
  }
}

// Helper function to demonstrate usage
function performExtraction(source, amount) {
  try {
    console.log(source.extract(amount));
  } catch (error) {
    console.error(`Extraction Error at ${source.location}: ${error.message}`);
  }
}

// --- Example Usage ---
const ironVein = new OreVein("Jagged Peaks", "Iron");
const blueCrystals = new CrystalDeposit("Whispering Caverns", "Blue");

performExtraction(ironVein, 50);          // Success
performExtraction(blueCrystals, 25);      // Success
performExtraction(ironVein, -10);         // Error: Quantity must be a positive number.
performExtraction(new ResourceSource("Unknown Origin"), 10); // Error: extract() must be implemented...

```

